from __future__ import annotations

import asyncio

import pytest
from ds.ai.agent import agent as smash_agent
from ds.ai.call_log import MAX_RESPONSE_CHARS, ToolCallLog, response_text
from ds.util.logging import enable_call_logs, log_call, logger
from ds.util.logging.calls import CALL_LOGGER
from pydantic_ai import Agent, ModelRetry, ToolReturn
from pydantic_ai.models.test import TestModel


@pytest.fixture
def records():
    found: list[dict] = []
    enable_call_logs()
    sink = logger.add(lambda m: found.append(dict(m.record["extra"])), filter=lambda r: "kind" in r["extra"])
    yield found
    logger.remove(sink)
    logger.disable(CALL_LOGGER)


def test_records_inside_a_tool_carry_its_call_id(records):
    agent = Agent(TestModel(), capabilities=[ToolCallLog()])

    @agent.tool_plain
    def lookup(tag: str) -> str:
        """Look a player up"""

        async def fetch() -> None:
            with log_call("http", "example", name="search"):
                pass

        asyncio.run(fetch())  # like ds.ai.startgg._run, from the tool's worker thread
        return tag

    agent.run_sync("hi")
    http, tool = records
    assert (http["kind"], tool["kind"]) == ("http", "tool")
    assert http["tool_call_id"] == tool["tool_call_id"]
    assert tool["tool_call_id"]
    assert (tool["name"], tool["source"]) == ("lookup", "smash-agent")
    assert tool["args"].startswith('{"tag":')
    assert tool["response"] == "a"  # what the tool gave back to the AI (TestModel sends "a")
    assert isinstance(tool["ms"], int)


def test_a_tool_response_is_text_and_cut_short():
    assert response_text("plain") == "plain"
    assert response_text({"rows": 2}) == '{\n  "rows": 2\n}'
    assert response_text(ToolReturn(return_value=[1, 2])) == "[\n  1,\n  2\n]"
    assert response_text(object()).startswith('"<object object')  # not JSON: its str()
    long = response_text("x" * (MAX_RESPONSE_CHARS + 50))
    assert (len(long), long[-1]) == (MAX_RESPONSE_CHARS + 1, "…")


def test_a_failing_tool_call_is_logged_with_its_error(records):
    agent = Agent(TestModel(), capabilities=[ToolCallLog()], retries=1)

    @agent.tool_plain
    def broken() -> str:
        """Always asks to retry"""
        raise ModelRetry("try again")

    with pytest.raises(Exception):  # noqa: B017, PT011  # pydantic-ai's own "exceeded retries"
        agent.run_sync("hi")
    errors = [r.get("error", "") for r in records if r["kind"] == "tool"]
    assert errors[0] == "ToolRetryError: try again"  # the model is asked to retry: logged
    assert "exceeded max retries" in errors[-1]


def test_the_smash_agent_logs_its_tool_calls():
    assert any(isinstance(c, ToolCallLog) for c in smash_agent.root_capability.capabilities)
